public class UploadController {
    public void uploadAvatar(MultipartFile file) throws Exception {
        String originalName = file.getOriginalFilename();
        if (originalName == null || !originalName.matches("^[a-zA-Z0-9_-]+\\.(jpg|png)$")) {
